const CACHE='deudas-pwa-v6';
const ASSETS=['/manifest.webmanifest','/icon-192.png','/icon-512.png','/icon-maskable.png','/icon-180.png','/icon-32.png','/app-version.js','/existing-install.js','/navigation-views.css','/navigation-views.js','/currency-ghost.css','/currency-ghost.js','/education-help-v2.css','/education-help-v2.js','/backup-validation.js','/backup-safe.js','/backup-preferences.js','/debt-engine.js','/candidate-finance.js','/reminders.js','/reminders-ui.js','/reminders-today.js','/foreground-notices.js','/foreground-notices-ui.js','/i18n.js'];
self.addEventListener('install',event=>event.waitUntil(caches.open(CACHE).then(cache=>cache.addAll(ASSETS))));
self.addEventListener('activate',event=>event.waitUntil(Promise.resolve()));
self.addEventListener('fetch',event=>{const req=event.request,url=new URL(req.url);if(req.method!=='GET'||url.origin!==location.origin)return;if(req.mode==='navigate'){event.respondWith(fetch(req).then(async response=>{if(response.ok&&!response.redirected&&(response.headers.get('content-type')||'').includes('text/html'))await(await caches.open(CACHE)).put('/offline-home',response.clone());return response}).catch(async()=>await caches.match('/offline-home')||Response.error()));return}if(ASSETS.includes(url.pathname))event.respondWith(caches.open(CACHE).then(cache=>cache.match(url.pathname)).then(cached=>cached||fetch(req)))});
